+           : (parent.width - width) / 2  // 竖向
+        y: root.orientation === Qt.Vertical
+           ? (root.visualPosition) * (root.height - height)  // 竖向：y 受 visualPosition 控制
+           : (parent.height - height) / 2  // 横向
