+            duration: Utils.animationSpeedMiddle
+            easing.type: Easing.OutQuint
+        }
+
+        PropertyAnimation {
+            target: indicator
+            property: "y"
+            from: parent.height / 2
+            to: (parent.height - indicator.implicitHeight) / 2
