+    // 收起切换按钮
+    ToolButton {
+        id: collapseButton
+        flat: true
+        width: 40
+        height: 38
+        // icon.name: collapsed ? "ic_fluent_chevron_right_20_regular" : "ic_fluent_chevron_left_20_regular"
