+                duration: Utils.animationSpeed
+                easing.type: Easing.OutCubic
+            }
+        }
+
+        onStateChanged: {
+            if (!indeterminate)
+                canvas.requestPaint()
+        }
+        on_ProgressChanged: {
+            if (!indeterminate)
+                canvas.requestPaint()
+        }
+        on_RingColorChanged: {
+            canvas.requestPaint()
+        }
+        onBackgroundColorChanged: {
+            if (state === ProgressRing.Running) {
+                canvas.requestPaint()
+            }
+        }
+    }

