+        function onLiveSpaceListReceived(data) {
+            spaceList = data
+            isLoading = false
+        }
+        function onLiveJoinedSpace(data) {
+            inSpace = true
+            currentSpace = data
+            chatMessages = []
+            if (data.users) {
+                onlineUsers = data.users
+            }
+        }
+        function onLiveLeftSpace() {
+            inSpace = false
+            currentSpace = {}
+            chatMessages = []
+            onlineUsers = []
+            audioEnabled = false
+            videoEnabled = false
+        }
