+        if (h < 15 || h >= 345) return "Red"
+        if (h < 35) return "Orange"
+        if (h < 50) return "Gold"
+        if (h < 70) return "Lime"
+        if (h < 140) return "Green"
+        if (h < 165) return "Teal"
+        if (h < 185) return "Aqua"
+        if (h < 205) return "Turquoise"
+        if (h < 255) return "Blue"
+        if (h < 290) return "Purple"
+        return "Pink"
+    }
