+        icon.name: "ic_fluent_cut_20_regular"
+        text: qsTr("Cut")
+        shortcut: "Ctrl+X"
+        enabled: target && target.selectedText && target.selectedText.length > 0 && canEdit()
+        onTriggered: {
+            if (!target || !target.selectedText || target.selectedText.length === 0) return
+            target.forceActiveFocus()
