+                    navigationBar.collapsedByAutoResize = true
+                }
+            } else {
+                if (navigationBar.collapsed && navigationBar.collapsedByAutoResize) {
+                    navigationBar.collapsed = false
+                    navigationBar.collapsedByAutoResize = false
+                }
+            }
+        }
+    }
+
+    Component.onCompleted: {
