+        Rectangle {
+            id: appLayer
+            width: parent.width + Utils.windowDragArea + radius
+            height: parent.height + Utils.windowDragArea + radius
+            color: Theme.currentTheme.colors.layerColor
+            border.color: Theme.currentTheme.colors.cardBorderColor
