+            pushEnter : Transition {
+                PropertyAnimation {
+                    property: "opacity"
+                    from: 0
+                    to: 1
+                    duration: Utils.appearanceSpeed
+                    easing.type: Easing.InOutQuad
+                }
+
+                PropertyAnimation {
+                    property: "y"
+                    from: pushEnterFromY
+                    to: 0
+                    duration: Utils.animationSpeedMiddle
+                    easing.type: Easing.OutQuint
